/* Route geometry shared by the simulation, renderer and authoring tools.

   A path is an array of control points [x, y, w, lane] in plate design pixels
   (841 × 1870):
     x, y  foot point of the lane centre (bottom-centre sprite anchor)
     w     the racer's on-screen sprite width at that point (depth scale)
     lane  horizontal distance in plate pixels between adjacent lanes (0 = single file)

   Positions are smoothed with a Catmull-Rom spline. The path parameter f (0..1)
   is proportional to distance measured in racer widths (∫ |dp| / w), so a racer
   moving at a constant world speed covers equal f per second whether the path is
   near the camera or far away. Fractions in plate data always use this metric. */
(function (WW) {
  'use strict';
  const SUB = 12;
  const cache = new WeakMap();

  function catmull(p0, p1, p2, p3, t) {
    const t2 = t * t, t3 = t2 * t;
    return 0.5 * ((2 * p1) + (-p0 + p2) * t + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 + (-p0 + 3 * p1 - 3 * p2 + p3) * t3);
  }

  function prepare(points) {
    let prepared = cache.get(points);
    if (prepared) return prepared;
    if (!points || points.length < 2) throw new Error('A path needs at least two points');
    const n = points.length, dense = [];
    const at = function (i) { return points[Math.max(0, Math.min(n - 1, i))]; };
    for (let i = 0; i < n - 1; i++) {
      const p0 = at(i - 1), p1 = at(i), p2 = at(i + 1), p3 = at(i + 2);
      for (let k = 0; k < SUB; k++) {
        const t = k / SUB;
        dense.push([
          catmull(p0[0], p1[0], p2[0], p3[0], t),
          catmull(p0[1], p1[1], p2[1], p3[1], t),
          p1[2] + (p2[2] - p1[2]) * t,
          (p1[3] || 0) + ((p2[3] || 0) - (p1[3] || 0)) * t
        ]);
      }
    }
    const last = points[n - 1];
    dense.push([last[0], last[1], last[2], last[3] || 0]);
    const cum = [0];
    for (let i = 1; i < dense.length; i++) {
      const a = dense[i - 1], b = dense[i];
      const len = Math.hypot(b[0] - a[0], b[1] - a[1]) / Math.max(1, (a[2] + b[2]) / 2);
      cum.push(cum[i - 1] + len);
    }
    const total = cum[cum.length - 1] || 1;
    prepared = { dense: dense, cum: cum.map(function (c) { return c / total; }), widths: total };
    cache.set(points, prepared);
    return prepared;
  }

  /* Returns {x, y, w, lane, tx, ty, f}; (tx, ty) is the unit direction of travel. */
  function sample(points, f) {
    const p = prepare(points);
    f = f < 0 ? 0 : f > 1 ? 1 : f;
    const cum = p.cum, d = p.dense;
    let lo = 0, hi = cum.length - 1;
    while (hi - lo > 1) {
      const mid = (lo + hi) >> 1;
      if (cum[mid] <= f) lo = mid; else hi = mid;
    }
    const span = cum[hi] - cum[lo] || 1;
    const t = (f - cum[lo]) / span;
    const a = d[lo], b = d[hi];
    let tx = b[0] - a[0], ty = b[1] - a[1];
    const len = Math.hypot(tx, ty) || 1;
    return {
      x: a[0] + (b[0] - a[0]) * t,
      y: a[1] + (b[1] - a[1]) * t,
      w: a[2] + (b[2] - a[2]) * t,
      lane: a[3] + (b[3] - a[3]) * t,
      tx: tx / len, ty: ty / len, f: f
    };
  }

  /* Path fraction of the point on the path closest to (x, y). */
  function project(points, x, y) {
    const p = prepare(points);
    let best = 0, bestD = Infinity;
    for (let i = 0; i < p.dense.length; i++) {
      const q = p.dense[i];
      const d = (q[0] - x) * (q[0] - x) + (q[1] - y) * (q[1] - y);
      if (d < bestD) { bestD = d; best = i; }
    }
    return p.cum[best];
  }

  /* Foot point for a racer at fraction f, lane value laneX (-1..1, continuous)
     and jump height fraction jumpH (0..1). Lanes offset horizontally. */
  function racerPoint(points, f, laneX, jumpH) {
    const s = sample(points, f);
    return {
      x: s.x + (laneX || 0) * s.lane,
      y: s.y - (jumpH || 0) * s.w * 0.42,
      groundY: s.y,
      w: s.w, tx: s.tx, ty: s.ty, f: s.f
    };
  }

  /* Length of the path in racer widths; useful when choosing segment lengths. */
  function widths(points) { return prepare(points).widths; }

  WW.path = { prepare: prepare, sample: sample, project: project, racerPoint: racerPoint, widths: widths };
})(globalThis.WW = globalThis.WW || {});
/* Wishweave Wonders — shared namespace, tuning values and small utilities.
   Loaded first. Every game script attaches to globalThis.WW so the same files
   run in the browser, the Android WebView and Node unit tests. */
(function (WW) {
  'use strict';

  WW.VERSION = '1.0.0';
  WW.DESIGN = { w: 841, h: 1870 };
  WW.PLATES = WW.PLATES || {};

  /* Gameplay timing in seconds and speeds in metres/second. The values marked
     "spec" come from docs/LEVEL1-GAMEPLAY-SPEC.md; the rest are tuning targets
     checked by tests/unit and tests/e2e. */
  WW.TUNING = {
    countdown: 3,
    purlSpeed: 5.0,
    purlAccel: 9,                 // m/s² when starting/stopping
    laneChangeTime: 0.22,
    jumpTime: 0.68,
    jumpAirborneAbove: 0.3,       // jump height fraction that clears Snagling's contact
    inputBufferTime: 0.15,        // swipe-up within this time before landing is replayed

    snagRevealToContact: 0.55,    // spec: visible reveal to possible contact
    snagContactWindow: 0.10,      // contact is tested for this long after the hop lands
    snagTangle: 0.5,              // spec: ankle tangle duration
    hitImmunity: 1.6,             // spec: post-hit damage immunity
    slowAfterHit: 0.6,            // speed multiplier while recovering footing
    slowAfterHitTime: 1.2,
    snagRetreat: 1.4,
    dropAheadF: 0.10,             // dropped thread lands this far ahead (path fraction)
    dropSpacingF: 0.07,
    recoveryLoopTime: 2.6,        // local loop that returns Purl to the landing entry
    failDelay: 1.2,

    ribbonUnfurl: 1.3,
    shortcutUnroll: 1.5,
    tasselLift: 0.45,
    tasselStagger: 0.3,
    butterflyEmerge: 0.7,
    butterflyFly: 1.7,
    butterflyPlace: 0.45,
    routeSettle: 0.25,            // pause after an opening completes before Purl moves

    pickupRadiusF: 0.035,         // path-fraction tolerance for collecting a thread
    dropPickupLane: 0.6,          // |lane - dropLane| must be below this to recover a drop
    cueRepeatAfter: 4,

    loopSpeed: 5.0,
    loopSpeedJitter: 0.04,
    loopReact: [0.45, 1.3],
    loopHesitateChance: 0.22,
    loopHesitate: [0.5, 1.2],
    loopHopMissChance: 0.3,
    loopStumble: 0.9,
    loopDropOnStumbleChance: 0.35,
    loopRecover: 1.4,

    finishWaitForLoop: 25
  };

  /* Deterministic PRNG (mulberry32). Only the race simulation consumes it. */
  WW.rng = function (seed) {
    let a = (seed >>> 0) || 1;
    const next = function () {
      a = (a + 0x6D2B79F5) >>> 0;
      let t = a;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
    return {
      next: next,
      range: function (lo, hi) { return lo + (hi - lo) * next(); },
      chance: function (p) { return next() < p; },
      pick: function (list) { return list[Math.floor(next() * list.length)]; }
    };
  };

  WW.util = {
    clamp: function (v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; },
    lerp: function (a, b, t) { return a + (b - a) * t; },
    smooth: function (t) { t = t < 0 ? 0 : t > 1 ? 1 : t; return t * t * (3 - 2 * t); },
    easeOutBack: function (t) { const c = 1.70158; t -= 1; return 1 + (c + 1) * t * t * t + c * t * t; },
    approach: function (value, target, maxDelta) {
      return value < target ? Math.min(value + maxDelta, target) : Math.max(value - maxDelta, target);
    },
    /* Critically damped follow, frame-rate independent. */
    damp: function (value, target, halfLife, dt) {
      return target + (value - target) * Math.pow(2, -dt / Math.max(halfLife, 1e-4));
    }
  };
})(globalThis.WW = globalThis.WW || {});

#!/usr/bin/env python3
"""Draw a plate's authored route data over the clean plate for visual checking.

  python3 tools/plate-overlay.py p01 out.png [--scale 0.6] [--approved] [--clean]

Draws Purl's three lanes (centre solid, sides dashed), Purl sprites at the route
start, at every event and at the exit (scaled by the path's w), Loop's route and
sprites, event markers with labels, the stitch tap target, feature geometry
(ribbon/shortcut bands, tassels, butterfly flight, Snagling, gate arch) and the
occluder polygons. --approved uses the approved screenshot as the backdrop
(useful for matching scale/position); --clean draws only sprites (no lines).
Geometry is evaluated by game/src/core/path.js through Node, so the overlay is
exactly what the game uses.
"""
import argparse
import json
import os
import subprocess

from PIL import Image, ImageDraw

REPO = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
KIT = os.path.join(REPO, 'kit', 'Wishweave-Level1-Complete-Visual-Kit')

NODE = r"""
const path=require('path'); const R=process.argv[1]; const id=process.argv[2];
for (const f of ['core/ww.js','core/path.js','data/asset-data.js','data/plates/'+id+'.js']) require(path.join(R,'game/src',f));
const P=WW.PLATES[id]; const out={plate:P, purl:{}, loop:{}};
const S=(pts,f,l)=>WW.path.racerPoint(pts,f,l||0,0);
const dense=(pts,lane)=>{const a=[];for(let i=0;i<=200;i++)a.push(S(pts,i/200,lane));return a;};
out.purl.lanes=[-1,0,1].map(l=>dense(P.purl.path,l));
const fs=new Set([0,1]); for(const e of P.purl.events||[]) if(typeof e.f==='number') fs.add(e.f);
out.purl.samples=[...fs].sort((a,b)=>a-b).map(f=>S(P.purl.path,f,0));
if(P.loop&&P.loop.path){ out.loop.line=dense(P.loop.path,0);
  const lf=new Set([0,0.5,1]); for(const e of P.loop.events||[]) if(typeof e.f==='number') lf.add(e.f);
  out.loop.samples=[...lf].sort((a,b)=>a-b).map(f=>S(P.loop.path,f,0)); }
out.events=(P.purl.events||[]).filter(e=>typeof e.f==='number').map(e=>({e, p:S(P.purl.path,e.f,e.lane||0)}));
out.loopEvents=((P.loop&&P.loop.events)||[]).filter(e=>typeof e.f==='number').map(e=>({e, p:S(P.loop.path,e.f,0)}));
out.frames=WW.ASSETS.frames; out.images=WW.ASSETS.images;
console.log(JSON.stringify(out));
"""

APPROVED = {'p01': '01-ribbon', 'p02': '02-shortcut', 'p03': '03-tassels', 'p04': '04-snagged',
            'p06': '06-butterfly', 'p07': '07-finish'}


def load(pid):
    res = subprocess.run(['node', '-e', NODE, REPO, pid], capture_output=True, text=True, check=True)
    return json.loads(res.stdout)


def sprite(data, cache, name, width):
    fr = data['frames'][name]
    key = fr['img']
    if key not in cache:
        cache[key] = Image.open(os.path.join(REPO, 'game', data['images'][key]['file'])).convert('RGBA')
    img = cache[key].crop((fr['x'], fr['y'], fr['x'] + fr['w'], fr['y'] + fr['h']))
    s = width / fr['w']
    img = img.resize((max(1, int(fr['w'] * s)), max(1, int(fr['h'] * s))), Image.LANCZOS)
    return img, fr['px'] * s, fr['py'] * s


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('plate')
    ap.add_argument('out')
    ap.add_argument('--scale', type=float, default=0.6)
    ap.add_argument('--approved', action='store_true')
    ap.add_argument('--clean', action='store_true')
    a = ap.parse_args()
    d = load(a.plate)
    P = d['plate']
    if a.approved:
        base = Image.open(os.path.join(KIT, 'approved', APPROVED[a.plate] + '.png')).convert('RGBA').resize((841, 1870))
    else:
        base = Image.open(os.path.join(REPO, 'game', d['images'][P['image']]['file'])).convert('RGBA').resize((841, 1870))
    layer = Image.new('RGBA', base.size, (0, 0, 0, 0))
    dr = ImageDraw.Draw(layer)
    cache = {}
    lines = not a.clean

    if lines:
        for occ in P.get('occluders', []):
            dr.polygon([tuple(p) for p in occ['poly']], fill=(255, 0, 255, 50), outline=(255, 0, 255, 220))
        for key in ('ribbon', 'shortcut'):
            band = (P.get(key) or {}).get('band')
            if band:
                for x, y, hw in band:
                    dr.line([(x - hw, y), (x + hw, y)], fill=(255, 140, 0, 200), width=3)
                dr.line([(x, y) for x, y, _ in band], fill=(255, 140, 0, 255), width=2)
        for i, lane in enumerate(d['purl']['lanes']):
            pts = [(p['x'], p['y']) for p in lane]
            dr.line(pts, fill=(255, 60, 90, 255) if i == 1 else (255, 160, 170, 160), width=4 if i == 1 else 2)
        if d['loop'].get('line'):
            dr.line([(p['x'], p['y']) for p in d['loop']['line']], fill=(0, 220, 230, 255), width=4)
        st = P.get('stitch')
        if st:
            dr.ellipse([st['x'] - st['r'], st['y'] - st['r'], st['x'] + st['r'], st['y'] + st['r']], outline=(255, 230, 0, 255), width=4)
        bf = P.get('butterfly')
        if bf:
            for k in ('flight', 'exit'):
                if bf.get(k):
                    dr.line([(p[0], p[1]) for p in bf[k]], fill=(255, 200, 0, 230), width=3)
        gate = P.get('gate')
        if gate and gate.get('arch'):
            dr.polygon([tuple(p) for p in gate['arch']], outline=(255, 255, 255, 230))

    for t in P.get('tassels', []):
        img, px, py = sprite(d, cache, 'prop.swinging-tassel', t['w'])
        layer.alpha_composite(img, (int(t['x'] - px), int(t['y'] - py)))
        if lines:
            dr.line([(t['x'], t['y']), (t['x'], t['y'] - t['lift'])], fill=(255, 255, 0, 200), width=2)
    for pv in P.get('previews', []):
        img, px, py = sprite(d, cache, 'prop.%s-thread' % ('golden' if pv['item'] == 'gold' else pv['item']), pv['size'])
        layer.alpha_composite(img, (int(pv['x'] - px), int(pv['y'] - py)))
    sn = P.get('snagling')
    if sn:
        for k, frame in (('hide', 'snag.peek'), ('peek', 'snag.alert')):
            if sn.get(k):
                img, px, py = sprite(d, cache, frame, sn[k]['w'])
                img.putalpha(img.getchannel('A').point(lambda v: v // 2 if k == 'hide' else v))
                layer.alpha_composite(img, (int(sn[k]['x'] - px), int(sn[k]['y'] - py)))
    if P.get('cameo'):
        c = P['cameo']
        img, px, py = sprite(d, cache, 'snag.peek', c['w'])
        layer.alpha_composite(img, (int(c['x'] - px), int(c['y'] - py)))
    if bf := P.get('butterfly'):
        r = bf['rest']
        img, px, py = sprite(d, cache, 'feat.butterfly-open', r['w'])
        layer.alpha_composite(img, (int(r['x'] - px), int(r['y'] - py)))

    for ev in d['events']:
        e, p = ev['e'], ev['p']
        if e['type'] == 'pickup':
            name = 'prop.%s-thread' % ('golden' if e['item'] == 'gold' else e['item'])
            img, px, py = sprite(d, cache, name, e.get('size', 60))
            layer.alpha_composite(img, (int(p['x'] - px), int(p['y'] - py)))
    for ev in d['loopEvents']:
        e, p = ev['e'], ev['p']
        if e['type'] == 'pickup':
            name = 'prop.%s-thread' % ('golden' if e['item'] == 'gold' else e['item'])
            img, px, py = sprite(d, cache, name, e.get('size', 40))
            layer.alpha_composite(img, (int(p['x'] - px), int(p['y'] - py)))
    for p in d['loop'].get('samples', []):
        img, px, py = sprite(d, cache, 'loop.run-left', p['w'])
        img.putalpha(img.getchannel('A').point(lambda v: v * 3 // 4))
        layer.alpha_composite(img, (int(p['x'] - px), int(p['y'] - py)))
    for p in d['purl']['samples']:
        img, px, py = sprite(d, cache, 'purl.run-left', p['w'])
        img.putalpha(img.getchannel('A').point(lambda v: v * 3 // 4))
        layer.alpha_composite(img, (int(p['x'] - px), int(p['y'] - py)))

    if lines:
        for ev in d['events'] + [{'e': dict(e['e'], type='L:' + e['e']['type']), 'p': e['p']} for e in d['loopEvents']]:
            e, p = ev['e'], ev['p']
            dr.ellipse([p['x'] - 9, p['y'] - 9, p['x'] + 9, p['y'] + 9], fill=(255, 255, 255, 255), outline=(0, 0, 0, 255))
            label = '%s %s f=%.3f' % (e['type'], e.get('item') or e.get('stitch') or e.get('kind') or '', e['f'])
            dr.rectangle([p['x'] + 12, p['y'] - 12, p['x'] + 14 + 7 * len(label), p['y'] + 4], fill=(0, 0, 0, 170))
            dr.text((p['x'] + 14, p['y'] - 10), label, fill=(255, 255, 255, 255))

    out = Image.alpha_composite(base, layer)
    out = out.resize((int(841 * a.scale), int(1870 * a.scale)), Image.LANCZOS)
    out.convert('RGB').save(a.out)
    print('wrote', a.out)


if __name__ == '__main__':
    main()
import sys
from PIL import Image, ImageDraw
src,out=sys.argv[1],sys.argv[2]; scale=float(sys.argv[3]) if len(sys.argv)>3 else 0.55
box=tuple(int(v) for v in sys.argv[4].split(',')) if len(sys.argv)>4 else (0,0,841,1870)
step=int(sys.argv[5]) if len(sys.argv)>5 else 100
im=Image.open(src).convert('RGB').resize((841,1870)).crop(box)
im=im.resize((int(im.width*scale),int(im.height*scale)),Image.LANCZOS)
d=ImageDraw.Draw(im); x0,y0=box[0],box[1]
for gx in range((x0//step+1)*step, box[2], step):
    X=int((gx-x0)*scale); d.line([(X,0),(X,im.height)],fill=(0,255,255),width=1); d.text((X+2,2),str(gx),fill=(255,255,0))
for gy in range((y0//step+1)*step, box[3], step):
