cat > /tmp/claude-0/-home-user-threadgame/283326c9-5b0d-5733-99e1-670739471e16/scratchpad/p0304/bin/check.py <<'EOF'
"""Composite check: plate + racers at given f/lanes with occluders applied (game-like), tassels lifted.
usage: python3 check.py <plate> <out.png> <spec-json> [scale] [crop x0,y0,x1,y1]
spec: {"purl":[[f,lane],...], "loop":[f,...], "lift":0..1, "snag":["hide","peek"], "items":[[who,f,lane,size,kind]]}"""
import json, os, subprocess, sys
from PIL import Image, ImageDraw
REPO = '/home/user/threadgame'
NODE = r"""
const path=require('path'); const R='/home/user/threadgame/game/src'; const id=process.argv[1]; const spec=JSON.parse(process.argv[2]);
for (const f of ['core/ww.js','core/path.js','data/asset-data.js','data/plates/'+id+'.js']) require(path.join(R,f));
const P=WW.PLATES[id];
const out={plate:P, frames:WW.ASSETS.frames, images:WW.ASSETS.images, purl:[], loop:[], items:[]};
for (const [f,l] of spec.purl||[]) out.purl.push(WW.path.racerPoint(P.purl.path,f,l,0));
for (const f of spec.loop||[]) out.loop.push(WW.path.racerPoint(P.loop.path,f,0,0));
for (const [who,f,l,size,kind] of spec.items||[]) { const p=WW.path.racerPoint(who==='loop'?P.loop.path:P.purl.path,f,l,0); p.size=size; p.kind=kind; out.items.push(p); }
console.log(JSON.stringify(out));
"""
def main():
    pid, outp, spec = sys.argv[1], sys.argv[2], json.loads(sys.argv[3])
    scale = float(sys.argv[4]) if len(sys.argv) > 4 else 0.6
    crop = tuple(int(v) for v in sys.argv[5].split(',')) if len(sys.argv) > 5 else None
    d = json.loads(subprocess.run(['node', '-e', NODE, pid, json.dumps(spec)], capture_output=True, text=True, check=True).stdout)
    P = d['plate']
    plate = Image.open(os.path.join(REPO, 'game', d['images'][P['image']]['file'])).convert('RGBA').resize((841, 1870))
    cache = {}
    def spr(name, w):
        fr = d['frames'][name]; k = fr['img']
        if k not in cache: cache[k] = Image.open(os.path.join(REPO, 'game', d['images'][k]['file'])).convert('RGBA')
        im = cache[k].crop((fr['x'], fr['y'], fr['x'] + fr['w'], fr['y'] + fr['h'])); s = w / fr['w']
        return im.resize((max(1, round(fr['w'] * s)), max(1, round(fr['h'] * s))), Image.LANCZOS), fr['px'] * s, fr['py'] * s
    canvas = plate.copy()
    lift = spec.get('lift', 0)
    for t in P.get('tassels', []):
        im, px, py = spr('prop.swinging-tassel', t['w']); y = t['y'] - t['lift'] * lift
        ImageDraw.Draw(canvas).line([(t['x'], 0), (t['x'], y + 4)], fill=(230, 180, 60, 255), width=4)
        canvas.alpha_composite(im, (round(t['x'] - px), round(y - py)))
    actors = []  # (groundY, image, x, y)
    for p in d['purl']:
        im, px, py = spr('purl.run-left', p['w']); actors.append((p['groundY'], im, p['x'] - px, p['y'] - py))
    for p in d['loop']:
        im, px, py = spr('loop.run-left', p['w']); actors.append((p['groundY'], im, p['x'] - px, p['y'] - py))
    for p in d['items']:
        im, px, py = spr('prop.%s-thread' % p['kind'], p['size']); actors.append((p['groundY'], im, p['x'] - px, p['y'] - py))
    sn = P.get('snagling') or {}
    for k in spec.get('snag', []):
        s = sn[k]; frame = {'hide': 'snag.peek', 'peek': 'snag.alert'}[k] if ':' not in k else k
        im, px, py = spr(frame, s['w']); actors.append((s['y'], im, s['x'] - px, s['y'] - py))
    for gy, im, x, y in sorted(actors, key=lambda a: a[0]):
        canvas.alpha_composite(im, (round(x), round(y)))
        # occluders: redraw plate pixels inside poly when this actor is behind (gy < behindY)
        for o in P.get('occluders', []):
            if gy < o['behindY']:
                mask = Image.new('L', canvas.size, 0); ImageDraw.Draw(mask).polygon([tuple(q) for q in o['poly']], fill=255)
                canvas.paste(plate, (0, 0), mask)
    if spec.get('outline'):
        dr = ImageDraw.Draw(canvas)
        for o in P.get('occluders', []): dr.polygon([tuple(q) for q in o['poly']], outline=(255, 0, 255, 255))
    if crop: canvas = canvas.crop(crop)
    canvas = canvas.resize((round(canvas.width * scale), round(canvas.height * scale)), Image.LANCZOS)
    canvas.convert('RGB').save(outp); print('wrote', outp)
main()
EOF
